var rect = (ctx, x, y, w, h, fill2) => {
  ctx.fillStyle = fill2;
  ctx.fillRect(x, y, w, h);
};
var circle = (ctx, cx, cy, r, fill2, stroke, lw = 1) => {
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  if (fill2) {
    ctx.fillStyle = fill2;
    ctx.fill();
  }
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }
};
var poly = (ctx, pts, fill2, stroke, lw = 1) => {
  ctx.beginPath();
  pts.forEach(([x, y], i) => i ? ctx.lineTo(x, y) : ctx.moveTo(x, y));
  ctx.closePath();
  if (fill2) {
    ctx.fillStyle = fill2;
    ctx.fill();
  }
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }
};
var line = (ctx, x1, y1, x2, y2, stroke, lw = 1) => {
  ctx.strokeStyle = stroke;
  ctx.lineWidth = lw;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
};
var ground = (ctx, x0, y0, s, rnd, light, dark, speckle = "rgba(0,0,0,0.12)") => {
  rect(ctx, x0, y0, s, s, rnd(0) > 0.5 ? light : dark);
  ctx.fillStyle = speckle;
  const n = 1 + Math.floor(rnd(1) * 4);
  for (let i = 0; i < n; i++) {
    ctx.fillRect(x0 + rnd(i * 2 + 3) * s, y0 + rnd(i * 2 + 4) * s, Math.max(1, s * 0.035), Math.max(1, s * 0.035));
  }
};
var block = (ctx, x0, y0, s, fill2, edge) => {
  rect(ctx, x0, y0, s, s, fill2);
  ctx.strokeStyle = edge;
  ctx.lineWidth = Math.max(1, s * 0.04);
  ctx.strokeRect(x0 + s * 0.02, y0 + s * 0.02, s * 0.96, s * 0.96);
};
